import java.util.*;
import java.util.stream.*;

public class Trace {
    public static void main(String[] a) {
        List<Integer> r = List.of(1,2,3,4,5).stream() // LAZY source
            .filter(n -> n % 2 == 1)                   // LAZY: no execution yet
            .peek(n -> System.out.println("seen:" + n)) // LAZY: side effect deferred
            .map(n -> n * 10)                          // LAZY: no execution yet
            .toList();                                 // TERMINAL: pipeline executes now
        System.out.println(r);
    }
}
// Output order: seen:1, seen:3, seen:5 (fused per element), then [10, 30, 50]
